SELECT result_tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (SELECT result_tags, timestamp, any(value) AS value FROM (SELECT if((lhs_is_info_metric) OR length(rhs_groups) = 0, lhs_original_group, arraySort(tag -> tag.1, arrayConcat(lhs_original_group, arrayDistinct(arrayFlatten(arrayMap(tags -> arrayFilter(tag -> NOT has(['__name__', 'instance', 'job'], tag.1) AND NOT has(arrayMap(tag -> tag.1, lhs_original_group), tag.1), tags), rhs_groups)))))) AS result_tags, timestamp AS timestamp, value AS value FROM (SELECT lhs.original_group AS lhs_original_group, lhs.timestamp AS timestamp, lhs.value AS value, (match(arrayElement(arrayMap(tag -> tag.2, arrayFilter(tag -> tag.1 = '__name__', lhs.original_group)), 1), {info_lhs_name_matcher_0_value:String})) AS lhs_is_info_metric, groupArrayIf(rhs.original_group, length(rhs.original_group) > 0) AS rhs_groups FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance', 'job'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, d.value AS value FROM (SELECT grid_base.id AS id, grid_base.tags AS tags, grid_base.eval_ts AS eval_ts, grid_base.eval_ts - toIntervalMillisecond({info_lhs_offset_ms:Int64}) AS eval_bound FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({info_lhs_start_ms:Int64}, {info_lhs_end_ms:Int64} + {info_lhs_step_ms:Int64}, {info_lhs_step_ms:Int64}))) AS eval_ts FROM (
            SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {info_lhs_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({info_lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({info_lhs_required_end_ms:Int64})
        ) AS series) AS grid_base) AS grid ASOF INNER JOIN (
            SELECT id, timestamp, value FROM timeSeriesData(`observability`.`prometheus`) WHERE timestamp >= fromUnixTimestamp64Milli({info_lhs_required_start_ms:Int64}) AND timestamp <= fromUnixTimestamp64Milli({info_lhs_required_end_ms:Int64}) AND id IN (SELECT DISTINCT src.id FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {info_lhs_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({info_lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({info_lhs_required_end_ms:Int64}))
        ) AS d ON grid.id = d.id AND grid.eval_bound >= d.timestamp WHERE d.timestamp >= grid.eval_ts - toIntervalMillisecond({info_lhs_offset_ms:Int64} + {info_lhs_lookback_ms:Int64}) AND NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) ARRAY JOIN time_series AS point)) AS lhs LEFT JOIN (SELECT any(original_group) AS original_group, join_group AS join_group, timestamp AS timestamp, any(value) AS value, metric_name FROM (SELECT original_group, join_group, timestamp, value, arrayElement(arrayMap(tag -> tag.2, arrayFilter(tag -> tag.1 = '__name__', original_group)), 1) AS metric_name FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance', 'job'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, d.value AS value FROM (SELECT grid_base.id AS id, grid_base.tags AS tags, grid_base.eval_ts AS eval_ts, grid_base.eval_ts - toIntervalMillisecond({offset_ms:Int64}) AS eval_bound FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({start_ms:Int64}, {end_ms:Int64} + {step_ms:Int64}, {step_ms:Int64}))) AS eval_ts FROM (
            SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE match(src.metric_name, {range_instant_matcher_0_value:String}) AND src.max_time >= fromUnixTimestamp64Milli({required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({required_end_ms:Int64})
        ) AS series) AS grid_base) AS grid ASOF INNER JOIN (
            SELECT id, timestamp, value FROM timeSeriesData(`observability`.`prometheus`) WHERE timestamp >= fromUnixTimestamp64Milli({required_start_ms:Int64}) AND timestamp <= fromUnixTimestamp64Milli({required_end_ms:Int64}) AND id IN (SELECT DISTINCT src.id FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE match(src.metric_name, {range_instant_matcher_0_value:String}) AND src.max_time >= fromUnixTimestamp64Milli({required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({required_end_ms:Int64}))
        ) AS d ON grid.id = d.id AND grid.eval_bound >= d.timestamp WHERE d.timestamp >= grid.eval_ts - toIntervalMillisecond({offset_ms:Int64} + {lookback_ms:Int64}) AND NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) ARRAY JOIN time_series AS point)) AS rhs_input) AS rhs_checked GROUP BY join_group, metric_name, timestamp HAVING throwIf(count() > 1, 'found duplicate series for info metric on identifying labels') = 0) AS rhs ON lhs.join_group = rhs.join_group AND lhs.timestamp = rhs.timestamp GROUP BY lhs.original_group, lhs.join_group, lhs.timestamp, lhs.value, (match(arrayElement(arrayMap(tag -> tag.2, arrayFilter(tag -> tag.1 = '__name__', lhs.original_group)), 1), {info_lhs_name_matcher_0_value:String}))) AS joined_rows) AS joined_result_rows GROUP BY result_tags, timestamp) AS grouped_rows GROUP BY result_tags ORDER BY result_tags
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
